/* Buildless game engine. Every decision is synchronous; motion illustrates it. */
(() => {
  'use strict';
  const builders = {};
  const roles = {
    lab:{title:'Лаборатория',role:'Химик-лаборант',lead:'Внешне пробы могут быть одинаковыми. Лаборант превращает наблюдение в измерение — и помогает команде принять решение о качестве.',day:'Смена начинается с подготовки приборов и проб. Специалист соблюдает методику, записывает результаты, сравнивает их с требованиями и сообщает об отклонениях. Один необычный результат — повод проверить, а не угадать причину.',tools:'Пробы, измерительные приборы, лабораторный журнал и методики.',skills:'Аккуратность, химия, внимание к деталям и умение работать с данными.',learned:'Настроил учебный прибор по эталону, измерил три пробы и оформил решения по кислотности и плотности.'},
    line:{title:'Линия розлива',role:'Оператор линии розлива',lead:'Бутылка проходит розлив, укупорку и этикетирование. Оператор видит весь процесс: замечает, на каком участке появляется отклонение, и действует по инструкции.',day:'Перед запуском проверяют готовность участка и параметры задания. Во время работы контролируют оборудование и продукцию. При отклонении важно вовремя отделить проблемную продукцию и подключить наставника — количество не заменяет качество.',tools:'Панель управления, задание на выпуск и средства визуального контроля.',skills:'Наблюдательность, дисциплина, понимание последовательности операций.',learned:'Настроил учебный розлив и этикетку, провёл пробный пуск и распределил шесть бутылок по результатам осмотра.'},
    engineering:{title:'Инженерный участок',role:'Инженер КИПиА',lead:'Датчик сообщает, что происходит на участке, контроллер обрабатывает сигнал, исполнительный механизм выполняет команду. Инженер ищет место, где эта связь нарушилась.',day:'Специалист сопоставляет показания, разбирается в сигнале и документации, проверяет гипотезу и работает в рамках допуска. Стажёр наблюдает и действует вместе с наставником. Самостоятельное вмешательство в оборудование в эту игру не входит.',tools:'Схемы, показания датчиков, средства диагностики и документация.',skills:'Логика, основы автоматики, системное мышление и ответственность.',learned:'Сопоставил показания трёх узлов, локализовал потерю сигнала и проверил результат вместе с наставником.'},
    warehouse:{title:'Склад',role:'Оператор склада',lead:'Найди товар по адресу, собери точный состав и проверь упаковку перед передачей заказа.',day:'Команда принимает упакованную продукцию с производства, размещает её и собирает заказы. Оператор работает с документами и учётом, кладовщик координирует работу. При расхождении важно записать наблюдаемый факт и передать его ответственному сотруднику. Логистика продолжает путь проверенного заказа.',tools:'Задание на комплектацию, адреса хранения, маркировка, терминал и сканер. Схема работы в игре условная.',skills:'Внимательность, сравнение данных, точность и работа в команде.',learned:'Собрал и сверил учебный заказ, сообщил о повреждении и проверил замену перед передачей в зону отгрузки.'}
  };
  const arrow='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg>';
  const check='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function button(action,text,value='',cls='secondary',attrs=''){return `<button type="button" class="${cls}" data-do="${action}" data-value="${esc(value)}" ${attrs}>${text}</button>`;}
  function mount(container,id,onComplete){
    if(id==='intro')return window.GameStory.mount(container,onComplete);
    if(!builders[id])return ()=>{};
    const role=roles[id], root=document.createElement('section');root.className=`shift shift--${id}`;root.setAttribute('aria-label',role.title);
    root.innerHTML=`<header class="shift-heading"><h2>${role.title}</h2><p>${role.lead}</p></header><div class="shift-content"></div><div class="shift-feedback" role="status" aria-live="polite" aria-atomic="true"></div><section class="shift-profession"><h3>Что делает ${role.role.toLowerCase().replace('кипиа','КИПиА')}</h3><p>${role.day}</p><details><summary>Инструменты и навыки профессии</summary><dl><div><dt>В работе</dt><dd>${role.tools}</dd></div><div><dt>Что пригодится</dt><dd>${role.skills}</dd></div></dl></details></section>`;
    container.replaceChildren(root);
    const content=root.querySelector('.shift-content'), note=root.querySelector('.shift-feedback'), timelines=new Set(), ghosts=new Set();let disposed=false,finished=false;
    const g=window.gsap,ctx=g?g.context(()=>{},root):null;let previousPhase=-1;
    const enabled=()=>!disposed&&window.GameMotion?.enabled()!==false&&!document.hidden;
    const say=(text,mood='think')=>window.GameMotion?.coach({mood,text});
    function settle(){timelines.forEach(t=>{t.totalProgress(1);t.kill();});timelines.clear();ghosts.forEach(n=>n.remove());ghosts.clear();}
    function animate(factory){if(!g||!enabled())return;ctx.add(()=>{const t=factory(g);if(t)timelines.add(t);});}
    function feedback(text,ok=false){note.className='shift-feedback '+(ok?'is-success':'is-error');note.innerHTML=text?`${ok?check:''}<div>${text}</div>`:'';say(text.replace(/<[^>]+>/g,''),ok?'success':'think');}
    function draw(html,phases,index,lesson){settle();note.innerHTML='';note.className='shift-feedback';content.innerHTML=`<ol class="shift-phases" aria-label="Этапы смены">${phases.map((p,i)=>`<li class="${i<index?'is-done':''} ${i===index?'is-current':''}" ${i===index?'aria-current="step"':''}><span>${i<index?check:i+1}</span>${p}</li>`).join('')}</ol><div class="shift-lesson"><span class="shift-lesson-dot"></span><p>${lesson}</p></div>${html}<p class="shift-simulation">Учебная модель: все параметры и ситуации вымышлены. На производстве применяют утверждённые методики и инструкции.</p>`;if(previousPhase>=0&&previousPhase!==index)content.scrollIntoView({block:'start',behavior:'instant'});previousPhase=index;}
    function flight(source,target,markup){if(!source||!target||!enabled())return;const a=source.getBoundingClientRect(),b=target.getBoundingClientRect(),n=document.createElement('div');n.className='shift-flight';n.innerHTML=markup||source.innerHTML;Object.assign(n.style,{left:a.left+'px',top:a.top+'px',width:a.width+'px',height:a.height+'px'});document.body.append(n);ghosts.add(n);animate(g=>g.timeline({onComplete:()=>{n.remove();ghosts.delete(n);}}).to(n,{x:b.left-a.left,y:b.top-a.top,scale:.72,rotation:8,duration:.65,ease:'power3.inOut'}).to(n,{opacity:0,scale:.3,duration:.18}));}
    function success(text){feedback(text,true);content.insertAdjacentHTML('beforeend',`<div class="shift-finish">${button('finish','Записать открытие '+arrow,'','primary')}</div>`);}
    const api={root,content,draw,feedback,say,animate,settle,flight,success,button,arrow,check,esc};const game=builders[id](api);
    function act(type,value,target){if(disposed||finished)return;if(type==='finish'&&game.done()){finished=true;onComplete({id,score:100,role:role.role,learned:game.result?.().learned||role.learned});return;}const keyboard=target?.matches(':focus-visible');game.act(type,value,target);if(keyboard&&target&&!target.isConnected&&!game.managesFocus){const replacement=[...content.querySelectorAll('[data-do]:not(:disabled)')].find(n=>n.dataset.do===type&&n.dataset.value===value)||content.querySelector('button:not(:disabled),input,select');replacement?.focus({preventScroll:true});}}
    function click(e){const b=e.target.closest('[data-do]');if(b&&root.contains(b)&&!b.disabled)act(b.dataset.do,b.dataset.value,b);}
    function input(e){const n=e.target.closest('[data-input]');if(n)game.input?.(n.dataset.input,n.value,n);}
    function drag(e){const n=e.target.closest('[data-drag]');if(!n)return;e.dataTransfer.setData('text/plain',n.dataset.drag);e.dataTransfer.effectAllowed='move';}
    function dragover(e){if(e.target.closest('[data-drop]'))e.preventDefault();}
    function drop(e){const n=e.target.closest('[data-drop]');if(!n)return;e.preventDefault();const value=e.dataTransfer.getData('text/plain');game.drop?.(n.dataset.drop,value,n);}
    function motion(e){root.classList.toggle('is-paused',!e.detail.enabled);if(!e.detail.enabled)settle();}
    root.addEventListener('click',click);root.addEventListener('input',input);root.addEventListener('change',input);root.addEventListener('dragstart',drag);root.addEventListener('dragover',dragover);root.addEventListener('drop',drop);document.addEventListener('ochakovo:motion',motion);
    game.start();
    return ()=>{disposed=true;settle();game.cleanup?.();if(ctx)ctx.revert();root.removeEventListener('click',click);root.removeEventListener('input',input);root.removeEventListener('change',input);root.removeEventListener('dragstart',drag);root.removeEventListener('dragover',dragover);root.removeEventListener('drop',drop);document.removeEventListener('ochakovo:motion',motion);};
  }
  const list=[{id:'intro',title:'История в движении',role:'Команда «Очаково»',minutes:3},...Object.keys(roles).map(id=>({id,title:roles[id].title,role:roles[id].role,minutes:id==='warehouse'?8:4}))];
  window.OchakovoShift={register:(id,builder)=>{builders[id]=builder;},roles,button,arrow,check,esc};
  window.GameMissions={list,mount};
})();
